output:
variable "environments" {
  type    = list(string)
  default = ["dev", "staging", "prod"]
}

resource "aws_s3_bucket" "env" {
  count = length(var.environments)

  bucket = "acme-${var.environments[count.index]}-data"

  tags = {
    Environment = var.environments[count.index]
  }
}

variable "buckets" {
  type = map(string)
  default = {
    uploads   = "acme-uploads"
    archives  = "acme-archives"
    logs      = "acme-logs"
  }
}

resource "aws_s3_bucket" "this" {
  for_each = var.buckets

  bucket = each.value

  tags = {
    Purpose = each.key
  }
}

variable "enable_monitoring" {
  type    = bool
  default = true
}

resource "aws_sns_topic" "monitoring" {
  count = var.enable_monitoring ? 1 : 0

  name = "monitoring-alerts"
}

variable "regions" {
  type    = list(string)
  default = ["us-east-1", "eu-west-1"]
}

resource "aws_sqs_queue" "regional" {
  for_each = toset(var.regions)

  name = "events-${each.key}"
}

variable "instance_types" {
  type    = list(string)
  default = ["t3.micro", "t3.small", "t3.medium"]
}

resource "aws_instance" "workers" {
  count = length(var.instance_types)

  ami           = var.ami_id
  instance_type = var.instance_types[count.index]

  tags = {
    Name = "worker-${count.index}"
  }
}

variable "ami_id" {
  type = string
}

variable "user_names" {
  type    = set(string)
  default = ["alice", "bob", "carol"]
}

resource "aws_iam_user" "this" {
  for_each = var.user_names

  name = each.key

  tags = {
    Team = "data"
  }
}

variable "create_dns_record" {
  type    = bool
  default = false
}

variable "app_hostname" {
  type    = string
  default = "app.example.com"
}

resource "aws_route53_record" "app" {
  count = var.create_dns_record ? 1 : 0

  zone_id = var.zone_id
  name    = var.app_hostname
  type    = "A"
  ttl     = 300
  records = [var.app_ip]
}

variable "zone_id" {
  type = string
}

variable "app_ip" {
  type = string
}

resource "aws_s3_bucket" "data" {
  for_each = toset(["images", "videos", "documents"])

  bucket = "acme-${each.key}"
}

resource "aws_s3_bucket_public_access_block" "data" {
  for_each = aws_s3_bucket.data

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

variable "features" {
  type = list(object({
    name    = string
    enabled = bool
  }))
  default = [
    { name = "beta-search", enabled = true },
    { name = "legacy-sync", enabled = false },
    { name = "new-billing", enabled = true },
  ]
}

locals {
  enabled_features = [for f in var.features : f.name if f.enabled]
}

resource "aws_sns_topic" "feature" {
  count = length(local.enabled_features)

  name = "feature-${local.enabled_features[count.index]}"
}

locals {
  services = {
    api     = "info"
    worker  = "debug"
    cron    = "warn"
  }
}

resource "aws_cloudwatch_log_group" "services" {
  for_each = local.services

  name              = "/services/${each.key}"
  retention_in_days = 7

  tags = {
    LogLevel = each.value
  }
}

variable "topics" {
  type = map(object({
    visibility = number
    retention  = number
  }))
  default = {
    orders = {
      visibility = 60
      retention  = 345600
    }
    refunds = {
      visibility = 120
      retention  = 86400
    }
  }
}

resource "aws_sqs_queue" "topic" {
  for_each = var.topics

  name                       = "${each.key}-queue"
  visibility_timeout_seconds = each.value.visibility
  message_retention_seconds  = each.value.retention
}

variable "environments" {
  type    = list(string)
  default = ["dev", "prod"]
}

module "env" {
  count   = length(var.environments)
  source  = "./modules/env-stack"

  environment = var.environments[count.index]
  bucket_name = "acme-${var.environments[count.index]}-state-copy"
}

variable "workloads" {
  type = map(object({
    domain = string
  }))
  default = {
    storefront = { domain = "shop.example.com" }
    checkout   = { domain = "pay.example.com" }
  }
}

module "workload" {
  for_each = var.workloads
  source   = "./modules/workload"

  name   = each.key
  domain = each.value.domain
}

variable "instance_count" {
  type    = number
  default = 3
}

resource "aws_instance" "batch" {
  count = var.instance_count

  ami           = var.ami_id
  instance_type = "t3.small"

  tags = {
    Name = format("batch-%02d", count.index + 1)
  }
}

variable "ami_id" {
  type = string
}

variable "ingress_rules" {
  type = map(object({
    cidr  = string
    port  = number
    proto = string
  }))
  default = {
    https = { cidr = "0.0.0.0/0", port = 443, proto = "tcp" }
    ssh   = { cidr = "10.0.0.0/8", port = 22, proto = "tcp" }
  }
}

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = var.ingress_rules

  security_group_id = var.security_group_id
  cidr_ipv4         = each.value.cidr
  from_port         = each.value.port
  to_port           = each.value.port
  ip_protocol       = each.value.proto
}

variable "security_group_id" {
  type = string
}

resource "aws_iam_policy" "file" {
  for_each = fileset("./policies", "*.json")

  name   = replace(each.value, ".json", "")
  policy = file("./policies/${each.value}")
}

variable "environment_buckets" {
  type = map(object({
    name       = string
    versioning = bool
  }))
  default = {
    dev = { name = "acme-dev-data", versioning = false }
    prod = { name = "acme-prod-data", versioning = true }
  }
}

resource "aws_s3_bucket" "env" {
  for_each = var.environment_buckets

  bucket = each.value.name

  tags = {
    Environment = each.key
    Versioning  = tostring(each.value.versioning)
  }
}

resource "aws_s3_bucket_versioning" "env" {
  for_each = { for k, v in var.environment_buckets : k => v if v.versioning }

  bucket = aws_s3_bucket.env[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

variable "enable_nat" {
  type    = bool
  default = false
}

resource "aws_nat_gateway" "this" {
  count = var.enable_nat ? 1 : 0

  allocation_id = var.nat_eip_id
  subnet_id     = var.public_subnet_id

  tags = {
    Name = "shared-nat"
  }
}

variable "nat_eip_id" {
  type = string
}

variable "public_subnet_id" {
  type = string
}

variable "static_names" {
  type    = list(string)
  default = ["primary", "secondary"]
}

variable "dynamic_queues" {
  type    = map(number)
  default = {
    low    = 30
    medium = 60
    high   = 120
  }
}

resource "aws_sqs_queue" "static" {
  count = length(var.static_names)

  name = "${var.static_names[count.index]}-queue"
}

resource "aws_sqs_queue" "dynamic" {
  for_each = var.dynamic_queues

  name                       = "${each.key}-queue"
  visibility_timeout_seconds = each.value
}

variable "teams" {
  type = map(list(string))
  default = {
    platform = ["alice", "dave"]
    data     = ["bob", "erin"]
  }
}

resource "aws_iam_group" "this" {
  for_each = var.teams

  name = each.key
}

resource "aws_iam_group_membership" "this" {
  for_each = var.teams

  name = each.key
  users = each.value
  group = aws_iam_group.this[each.key].name
}
